:root {
  --ink: #0a0f1c;
  --body: #4a5160;
  --navy: #0b1f5b;
  --subtle: #7b8190;
  --hairline: #e6e8ec;
  --surface: #f5f5f6;
  --swap: #eef3fd;
  --swap-ink: #3557a0;
  --oos: #fdeeec;
  --oos-ink: #b42318;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
