import React from "react";
import { AbsoluteFill, Easing, Img, Html5Audio, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import { loadFont as loadNews } from "@remotion/google-fonts/Newsreader";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";

const { fontFamily: SERIF } = loadNews("normal", { weights: ["400", "500"] });
loadNews("italic", { weights: ["400", "500"] });
const { fontFamily: SANS } = loadGeist("normal", { weights: ["400", "500", "600"] });
const { fontFamily: MONO } = loadMono("normal", { weights: ["400", "500"] });

const FPS = 60;
const s = (sec: number) => Math.round(sec * FPS);
const EO = Easing.bezier(0.16, 1, 0.3, 1);
const EIO = Easing.bezier(0.7, 0, 0.2, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const kf = (f: number, t: number[], v: number[], easing = EO) => interpolate(f, t.map(s), v, { ...clamp, easing });
const lin = (f: number, a: number, b: number, from = 0, to = 1, easing = EO) => interpolate(f, [s(a), s(b)], [from, to], { ...clamp, easing });

const C = {
  ink: "#0a0f1c",
  body: "#4a5160",
  navy: "#0b1f5b",
  subtle: "#7b8190",
  hairline: "#e6e8ec",
  surface: "#f5f5f6",
  swap: "#eef3fd",
  swapInk: "#3557a0",
  oos: "#fdeeec",
  oosInk: "#b42318",
  red: "#ff4d3d",
  hud: "rgba(214,226,255,0.62)",
  bg: "#04060c",
};

type Prod = { img: string; name: string; brand: string; size: string; price: number; qty?: number; aisle: string; note?: string };

const P: Record<string, Prod> = {
  chicken: { img: "0025313650000", name: "Heritage Farm Chicken Thighs", brand: "Heritage Farm", size: "1 lb", price: 3.99, qty: 2, aisle: "Aisle 101 · Chicken" },
  oatly: { img: "0019064664001", name: "Oatly Barista Edition Oat Milk", brand: "Oatly", size: "32 fl oz", price: 3.99, aisle: "Aisle 4 · Dairy alt.", note: "Dairy-free · instead of cream" },
  masala: { img: "0001111002370", name: "Private Selection Garam Masala", brand: "Private Selection", size: "1.94 oz", price: 5.99, aisle: "Aisle 3 · Spices" },
  tomatoes: { img: "0001111011618", name: "Kroger Crushed Tomatoes", brand: "Kroger", size: "28 oz", price: 1.89, aisle: "Aisle 3 · Canned" },
  rice: { img: "0001111015342", name: "Kroger Basmati Rice", brand: "Kroger", size: "2 lb", price: 3.99, aisle: "Aisle 2 · Rice & grains" },
  onion: { img: "0000000004093", name: "Jumbo Yellow Onions", brand: "Produce", size: "1 lb", price: 1.19, qty: 2, aisle: "Produce" },
  ginger: { img: "0000000094612", name: "Organic Ginger Root", brand: "Produce", size: "1 lb", price: 3.49, aisle: "Produce" },
  garlic: { img: "0000000004608", name: "Garlic", brand: "Produce", size: "1 ct", price: 0.89, aisle: "Produce" },
  naan: { img: "0087668101325", name: "Stonefire Original Naan", brand: "Stonefire", size: "26.4 oz", price: 6.99, aisle: "Aisle 457 · Bread" },
  cilantro: { img: "0000000004889", name: "Cilantro", brand: "Produce", size: "1 bunch", price: 0.99, aisle: "Produce" },
};
const ST: Prod = { img: "0001111003850", name: "Simple Truth Oat Milk", brand: "Simple Truth", size: "1 qt", price: 1.99, aisle: "Aisle 4 · Dairy alt." };
const OATLY2: Prod = { img: "0019064664002", name: "Oatly Original Oat Milk", brand: "Oatly", size: "32 fl oz", price: 3.99, aisle: "Aisle 4 · Dairy alt." };
const ORDER = ["chicken", "oatly", "masala", "tomatoes", "rice", "onion", "ginger", "garlic", "naan", "cilantro"];
const TOTAL = ORDER.reduce((n, k) => n + P[k].price * (P[k].qty ?? 1), 0);

const T = {
  phoneIn: 0.75,
  orbTap: 2.5,
  typeStart: 3.55,
  typeEnd: 4.55,
  toList: 4.75,
  listIn: 5.2,
  oos: 8.85,
  swapCard: 9.05,
  swapTap: 10.95,
  swapDone: 11.2,
  scrollBack: 11.75,
  mode1: 12.35,
  mode2: 13.05,
  mode3: 13.85,
  end: 14.85,
};

const money = (n: number) => `$${n.toFixed(2)}`;

const Words: React.FC<{
  text: string;
  start: number;
  end?: number;
  size: number;
  font?: string;
  italic?: boolean;
  color?: string;
  weight?: number;
  tracking?: string;
  stagger?: number;
  lh?: number;
  upper?: boolean;
}> = ({ text, start, end, size, font = SERIF, italic, color = "#fff", weight = 400, tracking = "-0.035em", stagger = 3, lh = 1.0, upper }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const lines = text.split("\n");
  let idx = 0;
  return (
    <div style={{ fontFamily: font, fontSize: size, lineHeight: lh, fontStyle: italic ? "italic" : "normal", color, fontWeight: weight, letterSpacing: tracking, textTransform: upper ? "uppercase" : "none" }}>
      {lines.map((line, li) => (
        <div key={li} style={{ whiteSpace: "nowrap" }}>
          {line.split(" ").map((w, wi) => {
            const i = idx++;
            const inP = spring({ frame: f - s(start) - i * stagger, fps, config: { damping: 200, stiffness: 180, mass: 0.6 } });
            const outP = end === undefined ? 0 : interpolate(f, [s(end) + i * 1.5, s(end) + i * 1.5 + 12], [0, 1], { ...clamp, easing: EIO });
            const y = (1 - inP) * 105 - outP * 105;
            return (
              <span key={wi} style={{ display: "inline-block", overflow: "hidden", verticalAlign: "top", paddingBottom: size * 0.12, marginBottom: -size * 0.12, paddingRight: italic ? size * 0.06 : 0 }}>
                <span style={{ display: "inline-block", transform: `translateY(${y}%)` }}>
                  {w}
                  {wi < line.split(" ").length - 1 ? " " : ""}
                </span>
              </span>
            );
          })}
        </div>
      ))}
    </div>
  );
};

const Typed: React.FC<{ text: string; start: number; end?: number; cps?: number; style?: React.CSSProperties; caret?: boolean }> = ({ text, start, end, cps = 42, style, caret = true }) => {
  const f = useCurrentFrame();
  const n = Math.max(0, Math.min(text.length, Math.floor(((f - s(start)) / FPS) * cps)));
  const vis = f >= s(start) && (end === undefined || f < s(end));
  const op = end === undefined ? 1 : lin(f, end - 0.15, end, 1, 0, EIO);
  if (!vis) return null;
  return (
    <span style={{ ...style, opacity: op }}>
      {text.slice(0, n)}
      {caret && <span style={{ opacity: Math.floor(f / 16) % 2 === 0 || n < text.length ? 1 : 0 }}>▍</span>}
    </span>
  );
};

const Hud: React.FC<{ children: React.ReactNode; start: number; end?: number; color?: string; size?: number; style?: React.CSSProperties }> = ({ children, start, end, color = C.hud, size = 15, style }) => {
  const f = useCurrentFrame();
  const a = lin(f, start, start + 0.35) * (end === undefined ? 1 : lin(f, end, end + 0.2, 1, 0, EIO));
  const clip = lin(f, start, start + 0.45) * 100;
  return (
    <div style={{ fontFamily: MONO, fontSize: size, letterSpacing: "0.16em", textTransform: "uppercase", color, opacity: a, clipPath: `inset(0 ${100 - clip}% 0 0)`, whiteSpace: "nowrap", ...style }}>
      {children}
    </div>
  );
};

const Background: React.FC = () => {
  const f = useCurrentFrame();
  const redGlow = lin(f, T.oos - 0.1, T.oos + 0.3) * lin(f, T.swapDone, T.swapDone + 0.8, 1, 0.0, EIO);
  const flash = interpolate(f, [s(T.oos), s(T.oos) + 3, s(T.oos) + 22], [0, 0.55, 0], clamp);
  const endFlash = interpolate(f, [s(T.end) - 2, s(T.end) + 2, s(T.end) + 26], [0, 0.18, 0], clamp);
  const drift = (f / FPS) * 14;
  const gx = kf(f, [0.75, 2, 8.4, 9.2, 12.0, 12.5, 14.8, 15.4], [960, 1340, 1340, 560, 560, 960, 960, 1420]);
  return (
    <AbsoluteFill style={{ background: C.bg }}>
      <AbsoluteFill style={{ background: `radial-gradient(900px 700px at ${gx}px 560px, rgba(40,78,190,0.38), rgba(11,31,91,0.12) 45%, transparent 70%)` }} />
      <AbsoluteFill style={{ background: `radial-gradient(800px 600px at 1360px 520px, rgba(255,60,40,${0.22 * redGlow}), transparent 70%)` }} />
      <AbsoluteFill
        style={{
          backgroundImage: "linear-gradient(rgba(255,255,255,0.045) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.045) 1px, transparent 1px)",
          backgroundSize: "96px 96px",
          backgroundPosition: `${-drift}px ${drift * 0.5}px`,
          maskImage: "radial-gradient(1100px 700px at 50% 50%, black 30%, transparent 80%)",
          WebkitMaskImage: "radial-gradient(1100px 700px at 50% 50%, black 30%, transparent 80%)",
          opacity: lin(f, 0.1, 1.2),
        }}
      />
      <AbsoluteFill style={{ background: "radial-gradient(1400px 900px at 50% 50%, transparent 55%, rgba(0,0,0,0.75) 100%)" }} />
      <AbsoluteFill style={{ background: C.red, opacity: flash * 0.35, mixBlendMode: "screen" }} />
      <AbsoluteFill style={{ background: "#fff", opacity: endFlash }} />
    </AbsoluteFill>
  );
};

const HudFrame: React.FC = () => {
  const f = useCurrentFrame();
  const a = lin(f, 0.2, 0.9);
  const secs = f / FPS;
  const tc = `T+${String(Math.floor(secs)).padStart(2, "0")}.${String(Math.floor((secs % 1) * 100)).padStart(2, "0")}`;
  const scene =
    secs < T.listIn ? "01 / VOICE" : secs < T.oos ? "02 / RECIPE → LIST" : secs < T.mode1 - 0.2 ? "03 / SUBSTITUTE" : secs < T.end ? "04 / FULFILLMENT" : "05 / BASKET";
  const corner = (pos: React.CSSProperties, rot: number) => (
    <div style={{ position: "absolute", width: 22, height: 22, borderTop: "1.5px solid rgba(214,226,255,0.5)", borderLeft: "1.5px solid rgba(214,226,255,0.5)", transform: `rotate(${rot}deg)`, ...pos }} />
  );
  const txt: React.CSSProperties = { position: "absolute", fontFamily: MONO, fontSize: 13, letterSpacing: "0.18em", color: "rgba(214,226,255,0.5)", textTransform: "uppercase" };
  return (
    <AbsoluteFill style={{ opacity: a }}>
      {corner({ left: 48, top: 48 }, 0)}
      {corner({ right: 48, top: 48 }, 90)}
      {corner({ right: 48, bottom: 48 }, 180)}
      {corner({ left: 48, bottom: 48 }, 270)}
      <div style={{ ...txt, left: 84, top: 52 }}>
        <span style={{ color: "#fff" }}>Basket</span> &nbsp;·&nbsp; The grocer’s agent
      </div>
      <div style={{ ...txt, right: 84, top: 52 }}>
        {scene} &nbsp;·&nbsp; <span style={{ color: "#fff" }}>{tc}</span>
      </div>
      <div style={{ ...txt, left: 84, bottom: 52 }}>Kroger On the Rhine · 39.1094° N 84.5143° W</div>
      <div style={{ ...txt, right: 84, bottom: 52, display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ width: 7, height: 7, borderRadius: 7, background: "#4ade80", opacity: 0.5 + 0.5 * Math.sin(f / 9) }} />
        Agent live · Runs on ZooWork
      </div>
    </AbsoluteFill>
  );
};

const Orb: React.FC<{ size: number; level: number }> = ({ size, level }) => {
  const f = useCurrentFrame();
  const t = f / FPS;
  const blob = (i: number) => {
    const a = t * (0.6 + i * 0.17) + i * 2.1;
    return { x: 50 + Math.cos(a) * 22, y: 48 + Math.sin(a * 1.3) * 18 };
  };
  const b = [0, 1, 2].map(blob);
  return (
    <div style={{ position: "relative", width: size, height: size }}>
      <div style={{ position: "absolute", inset: -size * 0.28, borderRadius: "50%", background: "radial-gradient(circle, rgba(37,99,235,0.35) 0%, transparent 68%)", opacity: 0.55 + level * 0.45, transform: `scale(${1 + level * 0.12})` }} />
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: "50%",
          overflow: "hidden",
          transform: `scale(${1 + level * 0.05})`,
          background: "radial-gradient(circle at 34% 28%, #e8f2ff 0%, #a9cdfb 26%, #5b9bf3 55%, #2a5fd6 80%, #1a3c9e 100%)",
          boxShadow: `inset 0 -${size * 0.08}px ${size * 0.18}px rgba(10,30,100,0.35), 0 ${size * 0.06}px ${size * 0.2}px rgba(37,99,235,0.25)`,
        }}
      >
        {b.map((p, i) => (
          <div key={i} style={{ position: "absolute", left: `${p.x}%`, top: `${p.y}%`, width: size * (0.55 - i * 0.1), height: size * (0.32 - i * 0.05), transform: "translate(-50%,-50%)", borderRadius: "50%", background: "rgba(255,255,255,0.75)", filter: `blur(${size * 0.07}px)` }} />
        ))}
        <div style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "radial-gradient(circle at 30% 22%, rgba(255,255,255,0.75), transparent 32%)" }} />
      </div>
    </div>
  );
};

const Thumb: React.FC<{ p: Prod; size?: number; dim?: boolean }> = ({ p, size = 52, dim }) => (
  <div style={{ width: size, height: size, borderRadius: size * 0.3, background: C.surface, overflow: "hidden", flexShrink: 0, opacity: dim ? 0.5 : 1, display: "flex", alignItems: "center", justifyContent: "center" }}>
    <Img src={staticFile(`${p.img}.jpg`)} style={{ width: "86%", height: "86%", objectFit: "contain", mixBlendMode: "multiply" }} />
  </div>
);

const Icon = {
  history: (c: string) => (
    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
      <path d="M3 3v5h5" />
      <path d="M12 7v5l4 2" />
