    </svg>
  ),
};

const Badge: React.FC<{ bg: string; color: string; icon?: React.ReactNode; children: React.ReactNode }> = ({ bg, color, icon, children }) => (
  <span style={{ marginTop: 5, display: "inline-flex", alignItems: "center", gap: 4, borderRadius: 999, background: bg, color, padding: "2px 8px", fontSize: 11, fontWeight: 500, whiteSpace: "nowrap", maxWidth: "100%" }}>
    {icon}
    {children}
  </span>
);

const ROW_H = 70;
const SCREEN_W = 393;
const SCREEN_H = 852;
const HEADER_H = 128;
const SWAP_H = 318;

const modeIndex = (f: number) => (f >= s(T.mode3) ? 2 : f >= s(T.mode2) ? 1 : 0);

const Row: React.FC<{ k: string; i: number }> = ({ k, i }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const enter = spring({ frame: f - s(T.listIn + 0.12) - i * 5, fps, config: { damping: 30, stiffness: 300, mass: 1 } });
  const inStore = f >= s(T.mode3) + 6;
  const isOatly = k === "oatly";
  const oos = isOatly && f >= s(T.oos) && f < s(T.swapDone);
  const swapped = isOatly && f >= s(T.swapDone);
  const sw = isOatly ? lin(f, T.swapDone, T.swapDone + 0.4) : 0;
  const p = swapped ? ST : P[k];
  const picked = inStore && f >= s(15.2) + i * 7;
  const checkIn = inStore ? lin(f, T.mode3 + 0.1, T.mode3 + 0.5) : 0;
  const pickP = picked ? spring({ frame: f - s(15.2) - i * 7, fps, config: { damping: 18, stiffness: 260 } }) : 0;
  const oosPulse = oos ? interpolate(f, [s(T.oos), s(T.oos) + 10, s(T.oos) + 30], [0, 1, 0.35], clamp) : 0;
  return (
    <div
      style={{
        height: ROW_H,
        display: "flex",
        alignItems: "center",
        gap: 12,
        borderTop: i === 0 ? "none" : `1px solid ${C.hairline}`,
        opacity: enter,
        transform: `translateY(${(1 - enter) * 14}px)`,
        filter: `blur(${(1 - enter) * 4 + (isOatly && f >= s(T.swapDone) ? (1 - sw) * 3 : 0)}px)`,
        position: "relative",
      }}
    >
      {oosPulse > 0 && <div style={{ position: "absolute", inset: "4px -12px", borderRadius: 18, background: C.oos, opacity: oosPulse }} />}
      <div style={{ width: 24 * checkIn, overflow: "hidden", flexShrink: 0, position: "relative" }}>
        <div style={{ width: 22, height: 22, borderRadius: 22, border: `1.5px solid ${picked ? C.ink : "#d5d8de"}`, background: picked ? C.ink : "#fff", display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${picked ? 0.8 + pickP * 0.2 : 1})` }}>
          {picked && Icon.check}
        </div>
      </div>
      <div style={{ position: "relative" }}>
        <Thumb p={p} dim={oos || picked} />
      </div>
      <div style={{ flex: 1, minWidth: 0, position: "relative" }}>
        <div style={{ fontSize: 14.5, fontWeight: 500, color: oos || picked ? C.subtle : C.ink, textDecoration: oos ? "line-through" : "none", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", lineHeight: 1.2 }}>{p.name}</div>
        <div style={{ fontSize: 12.5, color: C.subtle, marginTop: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
          {p.size} · {inStore ? p.aisle : p.brand}
        </div>
        {oos && <Badge bg={C.oos} color={C.oosInk}>Out of stock</Badge>}
        {!oos && swapped && (
          <Badge bg={C.swap} color={C.swapInk} icon={Icon.swap(C.swapInk)}>
            Swapped from Oatly · Store brand · −$2.00
          </Badge>
        )}
        {!oos && !swapped && p.note && (
          <Badge bg={C.surface} color={C.body} icon={Icon.history(C.body)}>
            {p.note}
          </Badge>
        )}
      </div>
      <div style={{ textAlign: "right", position: "relative" }}>
        <div style={{ fontSize: 14.5, fontWeight: 500, color: oos ? C.subtle : C.ink, textDecoration: oos ? "line-through" : "none", fontVariantNumeric: "tabular-nums" }}>{money(p.price * (p.qty ?? 1))}</div>
        {(p.qty ?? 1) > 1 && <div style={{ fontSize: 12.5, color: C.subtle }}>×{p.qty}</div>}
      </div>
    </div>
  );
};

const SwapOption: React.FC<{ p: Prod; reason: string; diff: string; primary?: boolean; pressed?: number; good?: boolean }> = ({ p, reason, diff, primary, pressed = 0, good }) => (
  <div style={{ width: 158, flexShrink: 0, borderRadius: 22, border: `1px solid ${primary ? "rgba(11,31,91,0.7)" : C.hairline}`, padding: 11, background: "#fff", transform: `scale(${1 - pressed * 0.04})` }}>
    <Thumb p={p} size={60} />
    <div style={{ marginTop: 8, fontSize: 13, lineHeight: 1.25, fontWeight: 500, height: 33, overflow: "hidden" }}>{p.name}</div>
    <div style={{ marginTop: 3, fontSize: 11.5, color: C.subtle, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{reason}</div>
    <div style={{ marginTop: 8, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
      <span style={{ fontSize: 13.5, fontWeight: 500 }}>{money(p.price)}</span>
      <span style={{ fontSize: 11, color: good ? "#047857" : C.subtle }}>{diff}</span>
    </div>
    <div style={{ marginTop: 9, height: 30, borderRadius: 30, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12.5, fontWeight: 500, background: primary ? C.navy : C.surface, color: primary ? "#fff" : C.ink }}>Swap</div>
  </div>
);

const MODE_LINE: Array<[string, string]> = [
  ["Delivery today.", "Through Instacart, arriving 5–6 PM."],
  ["Pickup today.", "Ready at Kroger On the Rhine, 5:30 PM."],
  ["Shopping in store.", "Sorted by aisle. Say it if it’s not on the shelf."],
];

const Screen: React.FC = () => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const listP = lin(f, T.toList, T.toList + 0.55, 0, 1, EIO);
  const live = f >= s(T.orbTap);
  const thinking = f >= s(T.typeEnd) && f < s(T.listIn + 0.3);
  const vol = live ? 0.35 + 0.35 * Math.abs(Math.sin(f / 5)) * Math.abs(Math.sin(f / 13 + 1)) : 0;
  const orbSize = interpolate(listP, [0, 1], [224, 60]);
  const orbX = interpolate(listP, [0, 1], [SCREEN_W / 2, 20 + 30]);
  const orbY = interpolate(listP, [0, 1], [492, 62 + 30]);
  const tapRing = interpolate(f, [s(T.orbTap), s(T.orbTap) + 30], [0, 1], clamp);

  const swapOpen = spring({ frame: f - s(T.swapCard), fps, config: { damping: 30, stiffness: 260 } }) * (1 - lin(f, T.swapDone, T.swapDone + 0.4, 0, 1, EIO));
  const scroll = kf(f, [T.oos - 0.05, T.oos + 0.45, T.scrollBack, T.scrollBack + 0.5], [0, 128, 128, 0], EIO);
  const sub = TOTAL - (f >= s(T.swapDone) ? 2 : 0);
  const countUp = kf(f, [T.listIn + 0.2, 8.1], [0, 1], Easing.bezier(0.3, 0, 0.2, 1));
  const shown = f < s(8.15) ? sub * countUp : sub;
  const mi = modeIndex(f);
  const pill = kf(f, [T.mode2, T.mode2 + 0.35, T.mode3, T.mode3 + 0.35], [0, 1, 1, 2]);
  const lineKey = mi;
  const lineP = lin(f, [0, T.mode2, T.mode3][mi], [0, T.mode2, T.mode3][mi] + 0.35);
  const barIn = spring({ frame: f - s(T.listIn + 0.35), fps, config: { damping: 32, stiffness: 300 } });
  const picked = f >= s(15.2) ? Math.min(10, Math.floor((f - s(15.2)) / 7) + 1) : 0;
  const barLabel = mi === 0 ? "Checkout on Instacart" : mi === 1 ? "Place pickup order" : "Finish shopping";
  const barSub = mi === 2 ? `${money(sub)} · ${picked} of 10 picked` : `${money(shown)} · 12 items`;

  const caption =
    f < s(T.typeStart)
      ? null
      : f < s(T.listIn + 0.2)
        ? { user: true, text: "Chicken tikka masala for 4" }
        : f < s(T.swapDone)
          ? { user: false, text: "Tikka masala for 4. Dairy-free, 10 items." }
          : { user: false, text: "Swapped to Simple Truth. Same aisle, $2 less." };
  const status = !live ? "Tap the orb to start talking" : thinking ? "Checking the shelves…" : f >= s(T.listIn + 0.3) ? "Speaking" : "Listening";

  return (
    <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg,#edf1f7 0%,#f3f5f8 45%,#f5f5f6 100%)", fontFamily: SANS, color: C.ink, overflow: "hidden" }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: HEADER_H - scroll + 4, opacity: listP, transform: `translateY(${(1 - listP) * 30}px)`, padding: "0 18px" }}>
        <div style={{ borderRadius: 30, border: `1px solid ${C.hairline}`, background: "#fff", padding: 7 }}>
          <div style={{ position: "relative", display: "grid", gridTemplateColumns: "1fr 1fr 1fr", borderRadius: 999, background: C.surface, padding: 4 }}>
            <div style={{ position: "absolute", top: 4, bottom: 4, left: 4, width: "calc((100% - 8px) / 3)", borderRadius: 999, background: C.navy, transform: `translateX(${pill * 100}%)` }} />
            {["Delivery", "Pickup", "In store"].map((l, i) => (
              <div key={l} style={{ position: "relative", height: 42, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14.5, fontWeight: 500, color: Math.round(pill) === i ? "#fff" : C.body }}>
                {l}
              </div>
            ))}
          </div>
          <div style={{ padding: "11px 14px 7px", fontSize: 14, lineHeight: 1.35, color: C.body, height: 46, overflow: "hidden" }}>
            <div key={lineKey} style={{ opacity: lineP, transform: `translateY(${(1 - lineP) * 8}px)` }}>
              <span style={{ color: C.ink }}>{MODE_LINE[mi][0]}</span> {MODE_LINE[mi][1]}
            </div>
          </div>
        </div>

        <div style={{ height: (SWAP_H + 14) * swapOpen, overflow: "visible", marginTop: 14 }}>
          {swapOpen > 0.01 && (
            <div style={{ height: SWAP_H, borderRadius: 30, border: `1px solid ${C.hairline}`, background: "#fff", padding: 18, opacity: Math.min(1, swapOpen * 1.4), transform: `translateY(${(1 - swapOpen) * 16}px) scale(${0.97 + 0.03 * swapOpen})`, transformOrigin: "top center", boxShadow: "0 20px 40px -24px rgba(180,35,24,0.35)" }}>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <div>
                  <div style={{ fontSize: 10.5, fontWeight: 500, letterSpacing: "0.12em", color: C.oosInk, textTransform: "uppercase" }}>Not on the shelf · Aisle 4</div>
                  <div style={{ marginTop: 3, fontFamily: SERIF, fontSize: 23, fontWeight: 500, letterSpacing: "-0.02em", lineHeight: 1.1 }}>Oatly Barista Edition</div>
                </div>
                <div style={{ fontSize: 12.5, color: C.subtle, marginTop: 2 }}>Skip</div>
              </div>
              <div style={{ display: "flex", gap: 9, marginTop: 12, marginRight: -18 }}>
                <SwapOption p={ST} reason="Store brand · same aisle · dairy-free" diff="$2.00 less" primary good pressed={interpolate(f, [s(T.swapTap), s(T.swapTap) + 4, s(T.swapTap) + 12], [0, 1, 0], clamp)} />
                <SwapOption p={OATLY2} reason="Same brand · same aisle" diff="Same price" />
              </div>
              <div style={{ marginTop: 8, fontSize: 10.5, color: C.subtle }}>Check the label for allergens before you buy.</div>
            </div>
          )}
        </div>

        <div style={{ marginTop: 14, borderRadius: 30, border: `1px solid ${C.hairline}`, background: "#fff", padding: "18px 18px 4px" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
            <div style={{ fontFamily: SERIF, fontSize: 27, fontWeight: 500, letterSpacing: "-0.02em", lineHeight: 1 }}>Your order</div>
            <div style={{ fontSize: 13.5, color: C.subtle }}>10 items</div>
          </div>
          <div style={{ marginTop: 6 }}>
            {ORDER.map((k, i) => (
              <Row key={k} k={k} i={i} />
            ))}
          </div>
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: 0,
          height: interpolate(listP, [0, 1], [SCREEN_H, HEADER_H]),
          background: `rgba(238,242,247,${0.86 * listP})`,
          backdropFilter: listP > 0.5 ? "blur(16px)" : undefined,
          borderBottom: listP > 0.9 ? "1px solid rgba(10,15,28,0.05)" : "none",
        }}
      />

      <div style={{ position: "absolute", top: 150, left: 0, right: 0, textAlign: "center", opacity: 1 - lin(f, T.toList - 0.05, T.toList + 0.3, 0, 1, EIO), transform: `translateY(${-lin(f, T.toList - 0.05, T.toList + 0.4, 0, 30, EIO)}px)` }}>
        <div style={{ fontFamily: SERIF, fontSize: 52, lineHeight: 0.95, fontWeight: 500, letterSpacing: "-0.035em" }}>
          What’s for
          <br />
          dinner?
        </div>
        <div style={{ marginTop: 16, fontSize: 16.5, color: C.body }}>Just say it. Your order builds itself.</div>
      </div>

      <div style={{ position: "absolute", left: orbX - orbSize / 2, top: orbY - orbSize / 2 }}>
        <Orb size={orbSize} level={thinking ? 0.25 + 0.25 * Math.sin(f / 4) : vol} />
        {tapRing > 0 && tapRing < 1 && <div style={{ position: "absolute", inset: -tapRing * 40, borderRadius: "50%", border: `2px solid rgba(37,99,235,${0.5 * (1 - tapRing)})` }} />}
      </div>

      <div
        style={{
          position: "absolute",
          left: interpolate(listP, [0, 1], [26, 96]),
          right: interpolate(listP, [0, 1], [26, 18]),
          top: interpolate(listP, [0, 1], [636, 64]),
          textAlign: listP < 0.5 ? "center" : "left",
        }}
      >
        <div style={{ fontSize: 13.5, fontWeight: 500, color: live ? C.navy : C.subtle, display: "flex", alignItems: "center", gap: 6, justifyContent: listP < 0.5 ? "center" : "flex-start" }}>
          {live && <span style={{ width: 6, height: 6, borderRadius: 6, background: C.navy, opacity: 0.4 + 0.6 * Math.abs(Math.sin(f / 10)) }} />}
          {status}
        </div>
        {caption && (
          <div style={{ marginTop: 4, fontSize: listP > 0.5 ? 14.5 : 17, lineHeight: 1.3, color: caption.user ? C.subtle : C.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
            {caption.user ? (
              <>
                “<Typed text={caption.text} start={T.typeStart} cps={26} caret={f < s(T.typeEnd + 0.2)} />”
              </>
            ) : (
              <span key={caption.text} style={{ opacity: lin(f, f < s(T.swapDone) ? T.listIn + 0.2 : T.swapDone, (f < s(T.swapDone) ? T.listIn + 0.2 : T.swapDone) + 0.3) }}>
                {caption.text}
              </span>
            )}
          </div>
        )}
      </div>

      <div style={{ position: "absolute", left: 18, right: 18, bottom: 30, transform: `translateY(${(1 - barIn) * 110}px)`, opacity: barIn }}>
        <div style={{ height: 66, borderRadius: 66, border: "1px solid #c9ced8", background: "rgba(255,255,255,0.96)", boxShadow: "0 18px 40px -18px rgba(11,31,91,0.35)", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 9px 0 26px" }}>
          <div style={{ lineHeight: 1.25 }}>
            <div style={{ fontSize: 15.5, fontWeight: 500 }}>{barLabel}</div>
            <div style={{ fontSize: 12.5, color: C.subtle, fontVariantNumeric: "tabular-nums" }}>{barSub}</div>
          </div>
          <div style={{ width: 48, height: 48, borderRadius: 48, background: C.navy, display: "flex", alignItems: "center", justifyContent: "center" }}>{Icon.arrow}</div>
        </div>
      </div>
      <div style={{ position: "absolute", left: "50%", bottom: 8, width: 134, height: 5, borderRadius: 5, background: C.ink, transform: "translateX(-50%)" }} />
      <StatusBar />
      <Taps />
    </div>
  );
};

