  <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 54, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "4px 34px 0 46px", fontSize: 16, fontWeight: 600, color: C.ink }}>
    <span>9:41</span>
    <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
      <svg width="18" height="12" viewBox="0 0 18 12">
        {[0, 1, 2, 3].map((i) => (
          <rect key={i} x={i * 4.6} y={9 - i * 3} width="3.2" height={3 + i * 3} rx="1" fill={C.ink} />
        ))}
      </svg>
      <svg width="16" height="12" viewBox="0 0 16 12">
        <path d="M8 11.5 5.6 9a3.4 3.4 0 0 1 4.8 0z M8 2.2c2.6 0 5 1 6.8 2.8l-1.5 1.5A7.4 7.4 0 0 0 8 4.3 7.4 7.4 0 0 0 2.7 6.5L1.2 5A9.5 9.5 0 0 1 8 2.2zm0 3.6c1.6 0 3.1.6 4.3 1.8l-1.5 1.5A4 4 0 0 0 8 7.9a4 4 0 0 0-2.8 1.2L3.7 7.6A6 6 0 0 1 8 5.8z" fill={C.ink} />
      </svg>
      <div style={{ width: 25, height: 12, borderRadius: 4, border: "1.2px solid rgba(10,15,28,0.4)", padding: 1.5, position: "relative" }}>
