      </div>
    </div>
  </div>
);

const TAPS: Array<{ t: number; x: number; y: number }> = [
  { t: T.orbTap, x: SCREEN_W / 2, y: 492 },
  { t: T.swapTap, x: 104, y: HEADER_H + 4 + 120 + 14 + 18 + 245 - 128 },
  { t: T.mode1, x: 86, y: HEADER_H + 4 + 7 + 4 + 21 },
  { t: T.mode2, x: 196, y: HEADER_H + 4 + 7 + 4 + 21 },
  { t: T.mode3, x: 306, y: HEADER_H + 4 + 7 + 4 + 21 },
];

const Taps: React.FC = () => {
  const f = useCurrentFrame();
  return (
    <>
      {TAPS.map((tp, i) => {
        const a = interpolate(f, [s(tp.t) - 14, s(tp.t) - 4, s(tp.t) + 6, s(tp.t) + 20], [0, 1, 1, 0], clamp);
        const press = interpolate(f, [s(tp.t) - 4, s(tp.t), s(tp.t) + 8], [1.25, 0.82, 1], clamp);
        const ring = interpolate(f, [s(tp.t), s(tp.t) + 22], [0, 1], clamp);
        if (a <= 0) return null;
        return (
          <div key={i} style={{ position: "absolute", left: tp.x, top: tp.y, pointerEvents: "none" }}>
            <div style={{ position: "absolute", width: 46, height: 46, left: -23, top: -23, borderRadius: 46, background: "rgba(10,15,28,0.22)", border: "2px solid rgba(255,255,255,0.9)", boxShadow: "0 4px 18px rgba(0,0,0,0.25)", opacity: a, transform: `scale(${press})` }} />
            {ring > 0 && ring < 1 && <div style={{ position: "absolute", width: 46, height: 46, left: -23, top: -23, borderRadius: 46, border: `2px solid rgba(11,31,91,${0.6 * (1 - ring)})`, transform: `scale(${1 + ring * 1.6})` }} />}
          </div>
        );
      })}
    </>
  );
};

const Phone: React.FC = () => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const tt = [T.phoneIn, 2.0, 3.6, 5.2, 8.45, 9.15, 12.0, 12.45, 14.7, 15.4];
  const rise = spring({ frame: f - s(T.phoneIn), fps, config: { damping: 22, stiffness: 70, mass: 1.1 } });
  const x = kf(f, tt, [380, 390, 390, 360, 360, -400, -400, 0, 0, 450]);
  const sc = kf(f, tt, [0.92, 1, 1, 1.05, 1.05, 1.04, 1.04, 0.98, 0.98, 0.9]);
  const ry = kf(f, tt, [-34, -13, -9, -5, -5, 13, 10, 0, 0, -16]);
  const rx = kf(f, tt, [8, 4, 3, 1, 1, 2, 2, 0, 0, 5]);
  const y = (1 - rise) * 1150;
  const rxi = (1 - rise) * 38;
  const rz = (1 - rise) * -10;
  const t = f / FPS;
  const fy = Math.sin(t * 1.3) * 6;
  const fry = Math.sin(t * 0.9) * 1.6;
  const modeKick = [T.mode1, T.mode2, T.mode3].reduce((n, m) => n + interpolate(f, [s(m), s(m) + 5, s(m) + 26], [0, 1, 0], clamp), 0);
  const swapKick = interpolate(f, [s(T.oos), s(T.oos) + 4, s(T.oos) + 30], [0, 1, 0], clamp);
  const shakeX = Math.sin(f * 2.1) * 7 * swapKick;
  const shine = ((ry + fry) / 40) * 100;
  if (f < s(T.phoneIn) - 1) return null;
  const W = SCREEN_W + 26;
  const H = SCREEN_H + 26;
  return (
