          </linearGradient>
        </defs>
        {hits.map((i, k) => {
          const c = i % COLS;
          const r = Math.floor(i / COLS);
          const x0 = ox + c * gap;
          const y0 = oy + r * gap;
          const x = interpolate(collapse, [0, 1], [x0, target.x]);
          const y = interpolate(collapse, [0, 1], [y0, target.y]);
          const p = lin(f, 10.42 + k * 0.08, 10.7 + k * 0.08);
          if (p <= 0) return null;
          return (
            <g key={i} opacity={k === 0 ? 1 : 1 - collapse}>
              <circle cx={x} cy={y} r={10 + (1 - p) * 30} fill="none" stroke={k === 0 ? "#fff" : "#9db8ff"} strokeWidth={1.5} opacity={p} />
            </g>
          );
        })}
      </svg>
      <div style={{ position: "absolute", left: ox, top: oy + ROWS * gap + 26, display: "flex", gap: 40, opacity: appear * (1 - collapse) }}>
        <div style={{ fontFamily: MONO, fontSize: 13, letterSpacing: "0.16em", color: C.hud, textTransform: "uppercase" }}>Moss · 4,014 products</div>
        <div style={{ fontFamily: MONO, fontSize: 13, letterSpacing: "0.16em", color: C.hud, textTransform: "uppercase" }}>In stock · dairy-free · store brand first</div>
      </div>
      <div style={{ position: "absolute", left: ox + 470, top: oy - 128, opacity: appear * (1 - collapse), textAlign: "right", width: 248 }}>
