          {ms.toFixed(1)}
          <span style={{ fontSize: 30, color: C.hud }}> ms</span>
        </div>
      </div>
      {hits.slice(0, 1).map((i) => {
        const c = i % COLS;
        const r = Math.floor(i / COLS);
        return (
          <div key={i} style={{ position: "absolute", left: ox + c * gap + 22, top: oy + r * gap - 34, opacity: hitP * (1 - collapse), fontFamily: MONO, fontSize: 13, letterSpacing: "0.14em", color: "#fff", textTransform: "uppercase", whiteSpace: "nowrap", background: "rgba(4,6,12,0.85)", padding: "8px 12px", border: "1px solid rgba(157,184,255,0.5)" }}>
